CREATE TABLE IF NOT EXISTS "games" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable key used by the client SDK and by dashboards, e.g. neon_racer. Never renumbered.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- desc | asc. Racing games rank by lowest time, shooters by highest score; a wrong default here silently inverts every board.
	"default_score_direction" VARCHAR(8) NOT NULL DEFAULT 'desc',
	-- Hash of the shared secret the client signs submissions with. Storing the hash means a leaked key can be rotated without reading it back.
	"submission_secret_hash" VARCHAR(255) NOT NULL,
	-- When the title was registered.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "games" IS 'One title. Everything below is scoped by game so a single deployment can serve a studio portfolio without cross-title rank leakage.';
COMMENT ON COLUMN "games"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "games"."code" IS 'Stable key used by the client SDK and by dashboards, e.g. neon_racer. Never renumbered.';
COMMENT ON COLUMN "games"."name" IS 'Display name.';
COMMENT ON COLUMN "games"."default_score_direction" IS 'desc | asc. Racing games rank by lowest time, shooters by highest score; a wrong default here silently inverts every board.';
COMMENT ON COLUMN "games"."submission_secret_hash" IS 'Hash of the shared secret the client signs submissions with. Storing the hash means a leaked key can be rotated without reading it back.';
COMMENT ON COLUMN "games"."created_at" IS 'When the title was registered.';

CREATE TABLE IF NOT EXISTS "players" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identity from the platform account system. Unique within a game, not globally, because the same person is a different player per title.
	"external_id" VARCHAR(120) NOT NULL,
	-- Title this player profile belongs to.
	"game_id" BIGINT NOT NULL,
	-- Name rendered on the board. Denormalised onto entries at read time, never snapshotted, so a rename fixes the whole history.
	"display_name" VARCHAR(40) NOT NULL,
	-- ISO 3166-1 alpha-2. Drives regional board scope; null when the player opted out of location.
	"country_code" CHAR(2),
	-- Hard ban. Banned players are filtered out of ranking queries rather than deleted, so their submissions stay available for investigation.
	"is_banned" BOOLEAN NOT NULL DEFAULT false,
	-- First seen.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "players" IS 'A player profile within one title. Ban state lives here rather than on a shared account so a cheat in one game does not implicitly erase another.';
COMMENT ON COLUMN "players"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "players"."external_id" IS 'Identity from the platform account system. Unique within a game, not globally, because the same person is a different player per title.';
COMMENT ON COLUMN "players"."game_id" IS 'Title this player profile belongs to.';
COMMENT ON COLUMN "players"."display_name" IS 'Name rendered on the board. Denormalised onto entries at read time, never snapshotted, so a rename fixes the whole history.';
COMMENT ON COLUMN "players"."country_code" IS 'ISO 3166-1 alpha-2. Drives regional board scope; null when the player opted out of location.';
COMMENT ON COLUMN "players"."is_banned" IS 'Hard ban. Banned players are filtered out of ranking queries rather than deleted, so their submissions stay available for investigation.';
COMMENT ON COLUMN "players"."created_at" IS 'First seen.';

CREATE UNIQUE INDEX "uq_players_game_external"
ON "players" ("game_id", "external_id");
CREATE INDEX "idx_players_game_country"
ON "players" ("game_id", "country_code");

CREATE TABLE IF NOT EXISTS "seasons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Title the season belongs to.
	"game_id" BIGINT NOT NULL,
	-- Short key, e.g. s7. Used in URLs and in reward configuration.
	"code" VARCHAR(40) NOT NULL,
	-- Display name shown above the board.
	"name" VARCHAR(120) NOT NULL,
	-- Inclusive start instant. Stored with a zone because a season boundary is a global moment, not a local date.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- Exclusive end instant. Submissions land in the season whose half-open interval contains them.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- Set after rewards are paid. Once true the boards are frozen and late submissions are rejected rather than silently reordering a paid-out ranking.
	"is_finalised" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seasons" IS 'A competitive period. Seasons are rows rather than a reset script because last season has to remain queryable after this one starts.';
COMMENT ON COLUMN "seasons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seasons"."game_id" IS 'Title the season belongs to.';
COMMENT ON COLUMN "seasons"."code" IS 'Short key, e.g. s7. Used in URLs and in reward configuration.';
COMMENT ON COLUMN "seasons"."name" IS 'Display name shown above the board.';
COMMENT ON COLUMN "seasons"."starts_at" IS 'Inclusive start instant. Stored with a zone because a season boundary is a global moment, not a local date.';
COMMENT ON COLUMN "seasons"."ends_at" IS 'Exclusive end instant. Submissions land in the season whose half-open interval contains them.';
COMMENT ON COLUMN "seasons"."is_finalised" IS 'Set after rewards are paid. Once true the boards are frozen and late submissions are rejected rather than silently reordering a paid-out ranking.';

CREATE UNIQUE INDEX "uq_seasons_game_code"
ON "seasons" ("game_id", "code");
CREATE INDEX "idx_seasons_game_start"
ON "seasons" ("game_id", "starts_at");

CREATE TABLE IF NOT EXISTS "leaderboards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Title the board belongs to.
	"game_id" BIGINT NOT NULL,
	-- Season the board is bound to. Null for all-time boards, which never reset.
	"season_id" BIGINT,
	-- Stable key, e.g. time_trial_monaco. The client asks for boards by code plus scope.
	"code" VARCHAR(60) NOT NULL,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- global | region | friends. Region and friends boards are the same rows filtered at read time, not separate stores.
	"scope" VARCHAR(16) NOT NULL DEFAULT 'global',
	-- daily | weekly | monthly | season | all_time. Defines the window an entry competes in.
	"period" VARCHAR(16) NOT NULL DEFAULT 'season',
	-- What is being ranked, e.g. lap_time_ms or kills. Names the field the submission must carry.
	"metric" VARCHAR(40) NOT NULL,
	-- desc | asc. Overrides the game default for boards that rank the other way.
	"score_direction" VARCHAR(8) NOT NULL DEFAULT 'desc',
	-- best | latest | sum. Best keeps a personal record, sum accumulates across submissions; the choice decides what an entry row means.
	"aggregation" VARCHAR(16) NOT NULL DEFAULT 'best',
	-- Retires a board without deleting its history.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "leaderboards" IS 'A board definition, not a list of rows. Scope and period are attributes of the definition because a daily global board and a weekly regional board rank the same submissions under different rules.';
COMMENT ON COLUMN "leaderboards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "leaderboards"."game_id" IS 'Title the board belongs to.';
COMMENT ON COLUMN "leaderboards"."season_id" IS 'Season the board is bound to. Null for all-time boards, which never reset.';
COMMENT ON COLUMN "leaderboards"."code" IS 'Stable key, e.g. time_trial_monaco. The client asks for boards by code plus scope.';
COMMENT ON COLUMN "leaderboards"."name" IS 'Display name.';
COMMENT ON COLUMN "leaderboards"."scope" IS 'global | region | friends. Region and friends boards are the same rows filtered at read time, not separate stores.';
COMMENT ON COLUMN "leaderboards"."period" IS 'daily | weekly | monthly | season | all_time. Defines the window an entry competes in.';
COMMENT ON COLUMN "leaderboards"."metric" IS 'What is being ranked, e.g. lap_time_ms or kills. Names the field the submission must carry.';
COMMENT ON COLUMN "leaderboards"."score_direction" IS 'desc | asc. Overrides the game default for boards that rank the other way.';
COMMENT ON COLUMN "leaderboards"."aggregation" IS 'best | latest | sum. Best keeps a personal record, sum accumulates across submissions; the choice decides what an entry row means.';
COMMENT ON COLUMN "leaderboards"."is_active" IS 'Retires a board without deleting its history.';

CREATE UNIQUE INDEX "uq_leaderboards_game_code_scope_period"
ON "leaderboards" ("game_id", "code", "scope", "period");
CREATE INDEX "idx_leaderboards_season"
ON "leaderboards" ("season_id");

CREATE TABLE IF NOT EXISTS "score_submissions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Title the run belongs to.
	"game_id" BIGINT NOT NULL,
	-- Who scored.
	"player_id" BIGINT NOT NULL,
	-- Season resolved from occurred_at at write time. Null for submissions outside any season window.
	"season_id" BIGINT,
	-- Which metric this value is, matched against leaderboards.metric. One run can feed several boards.
	"metric" VARCHAR(40) NOT NULL,
	-- The raw number, in the metric smallest unit - milliseconds, points, kills. Integer so ordering never depends on float comparison.
	"value" BIGINT NOT NULL,
	-- Run detail kept for review and replay: track, loadout, build number, input device. Schemaless because every title wants different fields.
	"context" JSONB,
	-- Client-generated key for the run. Unique per game so a retried upload after a dropped connection cannot post the same score twice.
	"idempotency_key" VARCHAR(80) NOT NULL,
	-- Build the score came from. Lets a whole board be invalidated when a build shipped with a physics bug.
	"client_version" VARCHAR(40),
	-- When the run happened on the client. Trusted only loosely; it is checked against received_at.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- When the server accepted it. This is the authoritative ordering for ties and for season assignment disputes.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- accepted | held | rejected. Only accepted submissions may become a leaderboard entry.
	"review_state" VARCHAR(16) NOT NULL DEFAULT 'accepted',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "score_submissions" IS 'The append-only record of every run ever posted. Nothing is updated in place except review_state, which is what makes a retroactive purge of a cheating build possible without losing honest scores.';
COMMENT ON COLUMN "score_submissions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "score_submissions"."game_id" IS 'Title the run belongs to.';
COMMENT ON COLUMN "score_submissions"."player_id" IS 'Who scored.';
COMMENT ON COLUMN "score_submissions"."season_id" IS 'Season resolved from occurred_at at write time. Null for submissions outside any season window.';
COMMENT ON COLUMN "score_submissions"."metric" IS 'Which metric this value is, matched against leaderboards.metric. One run can feed several boards.';
COMMENT ON COLUMN "score_submissions"."value" IS 'The raw number, in the metric smallest unit - milliseconds, points, kills. Integer so ordering never depends on float comparison.';
COMMENT ON COLUMN "score_submissions"."context" IS 'Run detail kept for review and replay: track, loadout, build number, input device. Schemaless because every title wants different fields.';
COMMENT ON COLUMN "score_submissions"."idempotency_key" IS 'Client-generated key for the run. Unique per game so a retried upload after a dropped connection cannot post the same score twice.';
COMMENT ON COLUMN "score_submissions"."client_version" IS 'Build the score came from. Lets a whole board be invalidated when a build shipped with a physics bug.';
COMMENT ON COLUMN "score_submissions"."occurred_at" IS 'When the run happened on the client. Trusted only loosely; it is checked against received_at.';
COMMENT ON COLUMN "score_submissions"."received_at" IS 'When the server accepted it. This is the authoritative ordering for ties and for season assignment disputes.';
COMMENT ON COLUMN "score_submissions"."review_state" IS 'accepted | held | rejected. Only accepted submissions may become a leaderboard entry.';

CREATE UNIQUE INDEX "uq_submissions_game_idempotency"
ON "score_submissions" ("game_id", "idempotency_key");
CREATE INDEX "idx_submissions_player_metric"
ON "score_submissions" ("player_id", "metric", "received_at");
CREATE INDEX "idx_submissions_game_metric_value"
ON "score_submissions" ("game_id", "metric", "review_state", "value");

CREATE TABLE IF NOT EXISTS "leaderboard_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Board this standing belongs to.
	"leaderboard_id" BIGINT NOT NULL,
	-- Player standing on the board.
	"player_id" BIGINT NOT NULL,
	-- Submission that produced the current value. Null for aggregated boards where no single run explains the total.
	"submission_id" BIGINT,
	-- Current value under the board aggregation rule. Rank is deliberately absent - see the table note.
	"score" BIGINT NOT NULL,
	-- When the score was first achieved. Earlier wins a tie, which stops two identical scores from swapping places on every query.
	"tiebreak_at" TIMESTAMPTZ NOT NULL,
	-- Last time the entry improved.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "leaderboard_entries" IS 'One standing per player per board. There is no rank column: rank is a window function over this index, because storing it would mean rewriting every row below a player on every improvement, and a friends board has a different rank for the same score anyway.';
COMMENT ON COLUMN "leaderboard_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "leaderboard_entries"."leaderboard_id" IS 'Board this standing belongs to.';
COMMENT ON COLUMN "leaderboard_entries"."player_id" IS 'Player standing on the board.';
COMMENT ON COLUMN "leaderboard_entries"."submission_id" IS 'Submission that produced the current value. Null for aggregated boards where no single run explains the total.';
COMMENT ON COLUMN "leaderboard_entries"."score" IS 'Current value under the board aggregation rule. Rank is deliberately absent - see the table note.';
COMMENT ON COLUMN "leaderboard_entries"."tiebreak_at" IS 'When the score was first achieved. Earlier wins a tie, which stops two identical scores from swapping places on every query.';
COMMENT ON COLUMN "leaderboard_entries"."updated_at" IS 'Last time the entry improved.';

CREATE UNIQUE INDEX "uq_entries_board_player"
ON "leaderboard_entries" ("leaderboard_id", "player_id");
CREATE INDEX "idx_entries_board_score"
ON "leaderboard_entries" ("leaderboard_id", "score", "tiebreak_at");

CREATE TABLE IF NOT EXISTS "anti_cheat_flags" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Submission that tripped the rule.
	"submission_id" BIGINT NOT NULL,
	-- Detector that fired, e.g. impossible_delta or clock_skew. A code rather than free text so rule precision can be measured.
	"rule_code" VARCHAR(60) NOT NULL,
	-- One to five. Low severity accumulates for review; high severity holds the submission immediately.
	"severity" SMALLINT NOT NULL DEFAULT 1,
	-- Evidence the detector captured: expected bounds, observed value, comparison sample. What a human reviewer actually reads.
	"detail" JSONB,
	-- pending | confirmed | dismissed. A dismissed flag stays as a row so detector false-positive rates are measurable.
	"verdict" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Operator who ruled on it. Null while pending or when auto-resolved.
	"reviewed_by" VARCHAR(120),
	-- When the detector fired.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When a verdict was recorded.
	"resolved_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "anti_cheat_flags" IS 'Detector output attached to a run, not to a player. Several flags can land on one submission, and keeping dismissals means the detectors themselves can be judged instead of quietly trusted.';
COMMENT ON COLUMN "anti_cheat_flags"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "anti_cheat_flags"."submission_id" IS 'Submission that tripped the rule.';
COMMENT ON COLUMN "anti_cheat_flags"."rule_code" IS 'Detector that fired, e.g. impossible_delta or clock_skew. A code rather than free text so rule precision can be measured.';
COMMENT ON COLUMN "anti_cheat_flags"."severity" IS 'One to five. Low severity accumulates for review; high severity holds the submission immediately.';
COMMENT ON COLUMN "anti_cheat_flags"."detail" IS 'Evidence the detector captured: expected bounds, observed value, comparison sample. What a human reviewer actually reads.';
COMMENT ON COLUMN "anti_cheat_flags"."verdict" IS 'pending | confirmed | dismissed. A dismissed flag stays as a row so detector false-positive rates are measurable.';
COMMENT ON COLUMN "anti_cheat_flags"."reviewed_by" IS 'Operator who ruled on it. Null while pending or when auto-resolved.';
COMMENT ON COLUMN "anti_cheat_flags"."created_at" IS 'When the detector fired.';
COMMENT ON COLUMN "anti_cheat_flags"."resolved_at" IS 'When a verdict was recorded.';

CREATE INDEX "idx_flags_submission"
ON "anti_cheat_flags" ("submission_id");
CREATE INDEX "idx_flags_queue"
ON "anti_cheat_flags" ("verdict", "severity", "created_at");

CREATE TABLE IF NOT EXISTS "achievements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Title the achievement belongs to.
	"game_id" BIGINT NOT NULL,
	-- Stable key, e.g. marathon_runner. Platform achievement ids map to this.
	"code" VARCHAR(60) NOT NULL,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- Player-facing text. Shown redacted when is_secret is true.
	"description" VARCHAR(400) NOT NULL,
	-- Gamerscore contribution. Kept small and integral so totals are a trivial sum.
	"points" SMALLINT NOT NULL DEFAULT 10,
	-- Hides name and description until unlocked. The criteria rows still exist and still track progress in the background.
	"is_secret" BOOLEAN NOT NULL DEFAULT false,
	-- Shows a progress bar. False means a single binary condition with no partial state worth displaying.
	"is_incremental" BOOLEAN NOT NULL DEFAULT false,
	-- Limits the achievement to one season. Null for permanent achievements.
	"season_id" BIGINT,
	-- When it stopped being obtainable. Existing unlocks survive; new progress is refused.
	"retired_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "achievements" IS 'A named goal. It holds no condition of its own - every condition lives in achievement_criteria, so a one-step and a five-step achievement are the same shape.';
COMMENT ON COLUMN "achievements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "achievements"."game_id" IS 'Title the achievement belongs to.';
COMMENT ON COLUMN "achievements"."code" IS 'Stable key, e.g. marathon_runner. Platform achievement ids map to this.';
COMMENT ON COLUMN "achievements"."name" IS 'Display name.';
COMMENT ON COLUMN "achievements"."description" IS 'Player-facing text. Shown redacted when is_secret is true.';
COMMENT ON COLUMN "achievements"."points" IS 'Gamerscore contribution. Kept small and integral so totals are a trivial sum.';
COMMENT ON COLUMN "achievements"."is_secret" IS 'Hides name and description until unlocked. The criteria rows still exist and still track progress in the background.';
COMMENT ON COLUMN "achievements"."is_incremental" IS 'Shows a progress bar. False means a single binary condition with no partial state worth displaying.';
COMMENT ON COLUMN "achievements"."season_id" IS 'Limits the achievement to one season. Null for permanent achievements.';
COMMENT ON COLUMN "achievements"."retired_at" IS 'When it stopped being obtainable. Existing unlocks survive; new progress is refused.';

CREATE UNIQUE INDEX "uq_achievements_game_code"
ON "achievements" ("game_id", "code");

CREATE TABLE IF NOT EXISTS "achievement_criteria" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Achievement this condition belongs to.
	"achievement_id" BIGINT NOT NULL,
	-- Ordinal of the step. Ordered criteria let an achievement describe a sequence, not just a set.
	"step_index" SMALLINT NOT NULL,
	-- Player-facing label for this step, e.g. Win 10 ranked matches.
	"description" VARCHAR(240) NOT NULL,
	-- Counter the step watches, matching the metric on incoming submissions or events.
	"metric" VARCHAR(40) NOT NULL,
	-- gte | lte | eq. Racing achievements need lte, most others gte.
	"comparison" VARCHAR(8) NOT NULL DEFAULT 'gte',
	-- Threshold the metric must reach for the step to complete.
	"target_value" BIGINT NOT NULL,
	-- True makes the step a chain link - progress only counts once the previous step completed. False lets steps fill in any order.
	"requires_previous" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "achievement_criteria" IS 'The conditions, one row per step. Modelling criteria as rows is what makes multi-step achievements, progress bars and partial-completion UI fall out without a rules engine or a parsed expression string.';
COMMENT ON COLUMN "achievement_criteria"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "achievement_criteria"."achievement_id" IS 'Achievement this condition belongs to.';
COMMENT ON COLUMN "achievement_criteria"."step_index" IS 'Ordinal of the step. Ordered criteria let an achievement describe a sequence, not just a set.';
COMMENT ON COLUMN "achievement_criteria"."description" IS 'Player-facing label for this step, e.g. Win 10 ranked matches.';
COMMENT ON COLUMN "achievement_criteria"."metric" IS 'Counter the step watches, matching the metric on incoming submissions or events.';
COMMENT ON COLUMN "achievement_criteria"."comparison" IS 'gte | lte | eq. Racing achievements need lte, most others gte.';
COMMENT ON COLUMN "achievement_criteria"."target_value" IS 'Threshold the metric must reach for the step to complete.';
COMMENT ON COLUMN "achievement_criteria"."requires_previous" IS 'True makes the step a chain link - progress only counts once the previous step completed. False lets steps fill in any order.';

CREATE UNIQUE INDEX "uq_criteria_achievement_step"
ON "achievement_criteria" ("achievement_id", "step_index");

CREATE TABLE IF NOT EXISTS "achievement_progress" (
	-- Player being tracked. Half of the composite primary key.
	"player_id" BIGINT,
	-- Step being tracked. Half of the composite primary key, so progress is addressable without a lookup.
	"criterion_id" BIGINT,
	-- Where the counter stands. Updated with a monotonic max or an increment depending on the metric, never recomputed from raw events at read time.
	"current_value" BIGINT NOT NULL DEFAULT 0,
	-- When this step hit its target. Null while incomplete; an achievement unlocks when no criterion row is still null.
	"completed_at" TIMESTAMPTZ,
	-- Last counter movement. Lets a stalled progression be detected without scanning the event stream.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("player_id", "criterion_id")
);

COMMENT ON TABLE "achievement_progress" IS 'Per-player, per-step counters. The composite key carries no surrogate id because the pair is the identity, and the row is created lazily on first progress so an unattempted achievement costs nothing.';
COMMENT ON COLUMN "achievement_progress"."player_id" IS 'Player being tracked. Half of the composite primary key.';
COMMENT ON COLUMN "achievement_progress"."criterion_id" IS 'Step being tracked. Half of the composite primary key, so progress is addressable without a lookup.';
COMMENT ON COLUMN "achievement_progress"."current_value" IS 'Where the counter stands. Updated with a monotonic max or an increment depending on the metric, never recomputed from raw events at read time.';
COMMENT ON COLUMN "achievement_progress"."completed_at" IS 'When this step hit its target. Null while incomplete; an achievement unlocks when no criterion row is still null.';
COMMENT ON COLUMN "achievement_progress"."updated_at" IS 'Last counter movement. Lets a stalled progression be detected without scanning the event stream.';

CREATE INDEX "idx_progress_criterion_completed"
ON "achievement_progress" ("criterion_id", "completed_at");

CREATE TABLE IF NOT EXISTS "player_achievements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player who unlocked it.
	"player_id" BIGINT NOT NULL,
	-- Achievement unlocked.
	"achievement_id" BIGINT NOT NULL,
	-- Unlock instant. Ordering these gives the profile activity feed for free.
	"unlocked_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Season the unlock happened in, resolved at write time. Null for unlocks outside a season.
	"season_id" BIGINT,
	-- Set for the first player in the title to unlock it. Denormalised because computing it later requires a global sort of unlock times.
	"is_first_in_game" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "player_achievements" IS 'The unlock record, separate from progress. Unlock is a fact with a timestamp and a reward consequence; progress is a mutable counter, and conflating the two makes both hard to audit.';
COMMENT ON COLUMN "player_achievements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "player_achievements"."player_id" IS 'Player who unlocked it.';
COMMENT ON COLUMN "player_achievements"."achievement_id" IS 'Achievement unlocked.';
COMMENT ON COLUMN "player_achievements"."unlocked_at" IS 'Unlock instant. Ordering these gives the profile activity feed for free.';
COMMENT ON COLUMN "player_achievements"."season_id" IS 'Season the unlock happened in, resolved at write time. Null for unlocks outside a season.';
COMMENT ON COLUMN "player_achievements"."is_first_in_game" IS 'Set for the first player in the title to unlock it. Denormalised because computing it later requires a global sort of unlock times.';

CREATE UNIQUE INDEX "uq_player_achievements_player_achievement"
ON "player_achievements" ("player_id", "achievement_id");
CREATE INDEX "idx_player_achievements_achievement_time"
ON "player_achievements" ("achievement_id", "unlocked_at");

CREATE TABLE IF NOT EXISTS "achievement_rewards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Achievement that pays this out.
	"achievement_id" BIGINT NOT NULL,
	-- currency | item | cosmetic | title | xp. Names the system that will fulfil the grant.
	"reward_type" VARCHAR(32) NOT NULL,
	-- Identifier within reward_type, e.g. a currency code or an item template code. Deliberately not a foreign key; the item catalogue lives in another service.
	"reward_ref" VARCHAR(80) NOT NULL,
	-- Units granted. One row per distinct reward, so a single unlock can pay several things.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "achievement_rewards" IS 'What an unlock pays out, configured as data. Changing a reward edits a row rather than shipping code, and past grants are unaffected because reward_grants snapshots what was actually paid.';
COMMENT ON COLUMN "achievement_rewards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "achievement_rewards"."achievement_id" IS 'Achievement that pays this out.';
COMMENT ON COLUMN "achievement_rewards"."reward_type" IS 'currency | item | cosmetic | title | xp. Names the system that will fulfil the grant.';
COMMENT ON COLUMN "achievement_rewards"."reward_ref" IS 'Identifier within reward_type, e.g. a currency code or an item template code. Deliberately not a foreign key; the item catalogue lives in another service.';
COMMENT ON COLUMN "achievement_rewards"."quantity" IS 'Units granted. One row per distinct reward, so a single unlock can pay several things.';

CREATE INDEX "idx_rewards_achievement"
ON "achievement_rewards" ("achievement_id");

CREATE TABLE IF NOT EXISTS "reward_grants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Unlock that triggered the payout.
	"player_achievement_id" BIGINT NOT NULL,
	-- Reward configuration used. Nullable so a reward row can be deleted without erasing the record that something was paid.
	"reward_id" BIGINT,
	-- Snapshot of the type at grant time.
	"reward_type" VARCHAR(32) NOT NULL,
	-- Snapshot of the identifier at grant time. Reconfiguring the achievement later must not rewrite what a player already received.
	"reward_ref" VARCHAR(80) NOT NULL,
	-- Snapshot of the amount actually granted.
	"quantity" INTEGER NOT NULL,
	-- Derived from the unlock and the reward. Unique so a retried fulfilment call cannot pay the same reward twice.
	"idempotency_key" VARCHAR(80) NOT NULL UNIQUE,
	-- pending | granted | failed. Fulfilment is an outbound call to another service and can fail independently of the unlock.
	"state" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- When the downstream service confirmed. Null while pending or failed.
	"granted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reward_grants" IS 'The payout ledger. It exists because unlocking and paying are separate failure domains - an unlock must never be rolled back because a currency service was briefly down, and a retry must not double-pay.';
COMMENT ON COLUMN "reward_grants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reward_grants"."player_achievement_id" IS 'Unlock that triggered the payout.';
COMMENT ON COLUMN "reward_grants"."reward_id" IS 'Reward configuration used. Nullable so a reward row can be deleted without erasing the record that something was paid.';
COMMENT ON COLUMN "reward_grants"."reward_type" IS 'Snapshot of the type at grant time.';
COMMENT ON COLUMN "reward_grants"."reward_ref" IS 'Snapshot of the identifier at grant time. Reconfiguring the achievement later must not rewrite what a player already received.';
COMMENT ON COLUMN "reward_grants"."quantity" IS 'Snapshot of the amount actually granted.';
COMMENT ON COLUMN "reward_grants"."idempotency_key" IS 'Derived from the unlock and the reward. Unique so a retried fulfilment call cannot pay the same reward twice.';
COMMENT ON COLUMN "reward_grants"."state" IS 'pending | granted | failed. Fulfilment is an outbound call to another service and can fail independently of the unlock.';
COMMENT ON COLUMN "reward_grants"."granted_at" IS 'When the downstream service confirmed. Null while pending or failed.';

CREATE INDEX "idx_grants_unlock"
ON "reward_grants" ("player_achievement_id");
CREATE INDEX "idx_grants_state"
ON "reward_grants" ("state", "granted_at");

